//! Generated by Codex. Adversarial Wasm and lifecycle-budget regression tests.

use super::invocation_epoch::EpochClock;
use super::invocation_limits::{InvocationContext, InvocationLimits};
use super::invocation_memory::InvocationMemory;
use mudu::error::ErrorCode;
use mudu_sys::task::sync::{sleep_blocking, spawn_thread};
use std::time::Duration;
use wasmtime::{Config, Engine, Instance, Memory, MemoryType, Module, Store};

fn engine() -> Engine {
    let mut config = Config::new();
    config.consume_fuel(true).epoch_interruption(true);
    Engine::new(&config).unwrap()
}

#[test]
#[cfg_attr(miri, ignore)]
fn aggregate_memory_budget_covers_multiple_memories_and_initial_allocation() {
    let engine = engine();
    let limits = InvocationLimits {
        memory_bytes: 2 * 65536,
        ..Default::default()
    };
    let mut store = Store::new(&engine, InvocationMemory::new(&limits));
    store.limiter(|memory| memory);
    Memory::new(&mut store, MemoryType::new(1, None)).unwrap();
    let second = Memory::new(&mut store, MemoryType::new(1, None)).unwrap();
    assert!(second.grow(&mut store, 1).is_err());
    assert!(Memory::new(&mut store, MemoryType::new(1, None)).is_err());
}

#[test]
#[cfg_attr(miri, ignore)]
fn fuel_interrupts_infinite_loop_including_module_start() {
    let engine = engine();
    let module = Module::new(&engine, "(module (func $start (loop br 0)) (start $start))").unwrap();
    let mut store = Store::new(&engine, ());
    store.set_fuel(100).unwrap();
    store.set_epoch_deadline(u64::MAX / 2);
    let error = Instance::new(&mut store, &module, &[]).unwrap_err();
    assert!(format!("{error:?}").contains("fuel"));
}

#[test]
#[cfg_attr(miri, ignore)]
fn epoch_interrupts_deadline_and_explicit_cancellation() {
    for cancel in [false, true] {
        let engine = engine();
        let _clock = EpochClock::start(engine.clone()).unwrap();
        let control = InvocationContext::new(InvocationLimits {
            timeout_ms: if cancel { 30_000 } else { 20 },
            ..Default::default()
        })
        .unwrap();
        let task_control = control.clone();
        let task = spawn_thread(move || {
            let module =
                Module::new(&engine, "(module (func (export \"spin\") (loop br 0)))").unwrap();
            let mut store = Store::new(&engine, ());
            store.set_fuel(u64::MAX).unwrap();
            store.set_epoch_deadline(1);
            store.epoch_deadline_callback(move |_| {
                task_control.check()?;
                Ok(wasmtime::UpdateDeadline::Continue(1))
            });
            let instance = Instance::new(&mut store, &module, &[]).unwrap();
            let spin = instance
                .get_typed_func::<(), ()>(&mut store, "spin")
                .unwrap();
            spin.call(&mut store, ()).is_err()
        })
        .unwrap();
        if cancel {
            sleep_blocking(Duration::from_millis(20));
            control.cancel();
        }
        assert!(task.join().unwrap());
    }
}

#[test]
fn cancellation_and_commit_have_an_explicit_boundary() {
    let cancelled = InvocationContext::new(Default::default()).unwrap();
    cancelled.cancel();
    assert_eq!(
        cancelled.begin_commit().unwrap_err().ec(),
        ErrorCode::Interrupted
    );
    let committed = InvocationContext::new(Default::default()).unwrap();
    committed.begin_commit().unwrap();
    committed.cancel();
    committed.check().unwrap();
}

#[test]
fn host_budgets_are_sticky_and_checked_before_more_work() {
    let control = InvocationContext::new(InvocationLimits {
        max_host_calls: 1,
        max_input_bytes: 8,
        max_output_bytes: 8,
        ..Default::default()
    })
    .unwrap();
    control.enter_host(8).unwrap();
    assert!(control.enter_host(1).is_err());
    assert!(control.check().is_err());
    let control = InvocationContext::new(InvocationLimits {
        max_output_bytes: 1,
        ..Default::default()
    })
    .unwrap();
    assert!(control.leave_host(vec![0; 2]).is_err());
    assert!(control.enter_host(0).is_err());
}

#[test]
fn invalid_configuration_is_rejected() {
    let limits = InvocationLimits {
        max_concurrent: 0,
        ..Default::default()
    };
    assert!(limits.validate().is_err());
    let limits = InvocationLimits {
        memory_bytes: usize::MAX,
        ..Default::default()
    };
    assert!(limits.validate().is_err());
}
